__mods['./normalizadores'] = function (module, exports, require) {
'use strict';
/**
 * Normalizadores: convertem o payload nativo de cada canal no "Comando Normalizado" (§12),
 * único formato que o restante do sistema conhece. Nenhuma regra de negócio aqui.
 *
 * Comando Normalizado:
 *   { idempotency_key, canal, id_externo_remetente, chat_id, nome_remetente, recebido_em,
 *     texto, arquivos: [{origem, file_id, nome, mime, tamanho}], callback: {id, dados}|null }
 *
 * Fases seguintes acrescentam normalizarEmail / normalizarForms / normalizarWhatsapp neste arquivo.
 */

/**
 * @param {object} update  Update da Bot API do Telegram
 * @returns {object|null}  null = update que o sistema ignora
 */
function normalizarTelegram(update) {
  if (!update || typeof update !== 'object' || update.update_id === undefined) return null;
  const cq = update.callback_query;
  const msg = update.message || (cq && cq.message);
  const de = cq ? cq.from : update.message && update.message.from;
  if (!msg || !de || de.is_bot) return null;
  // Só conversas privadas: evita expor dados de projetos em grupos onde o bot foi adicionado.
  if (!msg.chat || msg.chat.type !== 'private') return null;

  const arquivos = [];
  if (!cq) {
    const m = update.message;
    if (m.document) {
      arquivos.push({
        origem: 'telegram', file_id: m.document.file_id, nome: m.document.file_name || 'arquivo',
        mime: m.document.mime_type || 'application/octet-stream', tamanho: m.document.file_size || 0,
      });
    } else if (Array.isArray(m.photo) && m.photo.length) {
      const maior = m.photo[m.photo.length - 1];      // o Telegram manda vários tamanhos; o último é o maior
      arquivos.push({
        origem: 'telegram', file_id: maior.file_id, nome: `foto_${m.message_id}.jpg`,
        mime: 'image/jpeg', tamanho: maior.file_size || 0,
      });
    }
  }

  return {
    idempotency_key: `telegram:update:${update.update_id}`,
    canal: 'telegram',
    id_externo_remetente: String(de.id),
    chat_id: String(msg.chat.id),
    nome_remetente: [de.first_name, de.last_name].filter(Boolean).join(' ') || de.username || '',
    recebido_em: new Date(((update.message && update.message.date) || Date.now() / 1000) * 1000).toISOString(),
    texto: cq ? '' : String(update.message.text || update.message.caption || '').trim(),
    arquivos,
    callback: cq ? { id: String(cq.id), dados: String(cq.data || '') } : null,
  };
}

module.exports = { normalizarTelegram };

};
__mods['./seguranca'] = function (module, exports, require) {
'use strict';
/**
 * Segurança das entradas (§18, §20): segredos, assinaturas HMAC e rate limit.
 * Comparações sempre em tempo constante. `crypto` é built-in do Node; no n8n é preciso
 * NODE_FUNCTION_ALLOW_BUILTIN=crypto (já definido no docker-compose.yml).
 */
const crypto = require('crypto');

/** Compara dois segredos em tempo constante. Vazio/ausente nunca confere. */
function compararSegredo(recebido, esperado) {
  if (typeof recebido !== 'string' || typeof esperado !== 'string' || !recebido || !esperado) return false;
  const a = crypto.createHash('sha256').update(recebido).digest();
  const b = crypto.createHash('sha256').update(esperado).digest();
  return crypto.timingSafeEqual(a, b);
}

function hmacHex(raw, secret) {
  return crypto.createHmac('sha256', secret).update(typeof raw === 'string' ? raw : Buffer.from(raw)).digest('hex');
}

/** Assinatura "sha256=<hex>" (Forms/API interna). */
function verificarHmac(raw, assinatura, secret) {
  if (!secret || raw == null || typeof assinatura !== 'string') return false;
  const hex = assinatura.replace(/^sha256=/i, '').trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(hex)) return false;
  return crypto.timingSafeEqual(Buffer.from(hex, 'hex'), Buffer.from(hmacHex(raw, secret), 'hex'));
}

/** Header X-Hub-Signature-256 da Meta (WhatsApp Cloud API) — mesmo formato "sha256=<hex>". */
function verificarMeta(raw, assinatura, appSecret) {
  return verificarHmac(raw, assinatura, appSecret);
}

/**
 * Janela deslizante: `historico` = datas (ISO/ms) das requisições anteriores do remetente.
 * @returns {{ok:boolean, restantes:number, tentarEmS:number}}
 */
function rateLimit(historico, limite, agora = Date.now(), janelaMs = 60000) {
  const t0 = agora - janelaMs;
  const recentes = (historico || []).map((d) => new Date(d).getTime()).filter((t) => t > t0 && t <= agora).sort((x, y) => x - y);
  const ok = recentes.length < limite;
  return {
    ok,
    restantes: Math.max(0, limite - recentes.length - (ok ? 1 : 0)),
    tentarEmS: ok ? 0 : Math.ceil((recentes[recentes.length - limite] + janelaMs - agora) / 1000),
  };
}

module.exports = { compararSegredo, verificarHmac, verificarMeta, rateLimit, hmacHex };

};
